import app from 'flarum/common/app';
const url = path => app.forum.attribute('apiUrl') + '/kiosk' + path;
export function call(method, path, body, params) {
  return app.request({
    method,
    url: url(path),
    body: body ? {
      data: body
    } : undefined,
    params
  });
}
export const store = lookup => call('GET', '/store', undefined, lookup);
export const checkout = (priceId, provider, options = {}) => call('POST', '/checkout', {
  priceId,
  provider,
  ...options
});
export const bump = discussionId => call('POST', `/discussions/${discussionId}/bump`);
export const tips = discussionId => call('GET', `/discussions/${discussionId}/tips`);
export const myPurchases = () => call('GET', '/purchases');
export const purchase = number => call('GET', `/purchases/${number}`);
export const confirm = number => call('POST', `/purchases/${number}/confirm`);
export const cancel = number => call('POST', `/purchases/${number}/cancel`);
export const switchPlan = (number, priceId) => call('POST', `/purchases/${number}/switch`, {
  priceId
});
export const addSeat = (number, username) => call('POST', `/purchases/${number}/seats`, {
  username
});
export const removeSeat = (number, userId) => call('DELETE', `/purchases/${number}/seats/${userId}`);
export const checkCoupon = (priceId, code) => call('POST', '/coupons/check', {
  priceId,
  code
});
export const selling = {
  get: () => call('GET', '/selling'),
  connect: (provider, fields = {}) => call('POST', `/selling/accounts/${provider}`, fields),
  remove: provider => call('DELETE', `/selling/accounts/${provider}`),
  terms: terms => call('POST', '/selling/terms', {
    terms
  }),
  items: q => call('GET', '/selling/items', undefined, {
    q
  }),
  save: (id, body) => call('POST', id ? `/selling/listings/${id}` : '/selling/listings', body),
  remove_listing: id => call('DELETE', `/selling/listings/${id}`),
  refund: number => call('POST', `/selling/sales/${number}/refund`)
};
flarum.reg.add('ernestdefoe-kiosk', 'common/api', { call: call,store: store,checkout: checkout,bump: bump,tips: tips,myPurchases: myPurchases,purchase: purchase,confirm: confirm,cancel: cancel,switchPlan: switchPlan,addSeat: addSeat,removeSeat: removeSeat,checkCoupon: checkCoupon,selling: selling, });